	public static final void FSM100_event_1Event(TextArea t) {
		FSM100_activated = true;
		while (!MultiSpec_1_RVMLock.tryLock()) {
			Thread.yield();
		}

		CachedWeakReference wr_t = null;
		Tuple2<FSM100Monitor_Set, FSM100Monitor> matchedEntry = null;
		boolean cachehit = false;
		if ((t == FSM100_t_Map_cachekey_t) ) {
			matchedEntry = FSM100_t_Map_cachevalue;
			cachehit = true;
		}
		else {
			wr_t = new CachedWeakReference(t) ;
			{
				// FindOrCreateEntry
				Tuple2<FSM100Monitor_Set, FSM100Monitor> node_t = FSM100_t_Map.getNodeEquivalent(wr_t) ;
				if ((node_t == null) ) {
					node_t = new Tuple2<FSM100Monitor_Set, FSM100Monitor>() ;
					FSM100_t_Map.putNode(wr_t, node_t) ;
					node_t.setValue1(new FSM100Monitor_Set() ) ;
				}
				matchedEntry = node_t;
			}
		}
		// D(X) main:1
		FSM100Monitor matchedLeaf = matchedEntry.getValue2() ;
		if ((matchedLeaf == null) ) {
			if ((wr_t == null) ) {
				wr_t = new CachedWeakReference(t) ;
			}
			if ((matchedLeaf == null) ) {
				// D(X) main:4
				FSM100Monitor created = new FSM100Monitor(FSM100_timestamp++) ;
				matchedEntry.setValue2(created) ;
				FSM100Monitor_Set enclosingSet = matchedEntry.getValue1() ;
				enclosingSet.add(created) ;
			}
			// D(X) main:6
			FSM100Monitor disableUpdatedLeaf = matchedEntry.getValue2() ;
			disableUpdatedLeaf.setDisable(FSM100_timestamp++) ;
		}
		// D(X) main:8--9
		FSM100Monitor_Set stateTransitionedSet = matchedEntry.getValue1() ;
		stateTransitionedSet.event_event_1(t);

		if ((cachehit == false) ) {
			FSM100_t_Map_cachekey_t = t;
			FSM100_t_Map_cachevalue = matchedEntry;
		}

		MultiSpec_1_RVMLock.unlock();
	}

